import java.util.Scanner;

public class Main {
    static long pow_mod(long base, int exp, int mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        final long MOD = 1000000007;

        if (k == 0) {
            System.out.println(pow_mod(p, p - 1, MOD));
            return;
        }
        if (k == 1) {
            System.out.println(pow_mod(p, p, MOD));
            return;
        }

        boolean[] visited = new boolean[p + 1];
        int cycle_len = 1;
        long val = k;
        visited[1] = true;

        while (!visited[(int) val]) {
            visited[(int) val] = true;
            val = (val * k) % p;
            cycle_len++;
        }

        long exponent = (p - 1) / cycle_len;
        System.out.println(pow_mod(p, (int) exponent, MOD));
    }
}
